const items = $input.all();
const detections = items.map(item => item.json);
const imgW = 480, imgH = 270, videoRealW = 1920, videoRealH = 1080;
const scale = videoRealW / imgW;

let validBoxes = [];
const getArea = (box) => (box.xmax - box.xmin) * (box.ymax - box.ymin);
const totalArea = imgW * imgH;
detections.forEach(d => {
    if (d.label === 'person' && d.score > 0.4) {
        const coverage = getArea(d.box) / totalArea;
        if (coverage > 0.02 && coverage < 0.45) validBoxes.push({ box: d.box, score: d.score });
    }
});
validBoxes.sort((a, b) => b.score - a.score);
let topBoxes = validBoxes.slice(0, 3).map(v => v.box);
let bestBox = topBoxes.length > 0 ? {
    xmin: topBoxes.reduce((s,b)=>s+b.xmin,0)/topBoxes.length,
    xmax: topBoxes.reduce((s,b)=>s+b.xmax,0)/topBoxes.length,
    ymin: topBoxes.reduce((s,b)=>s+b.ymin,0)/topBoxes.length,
    ymax: topBoxes.reduce((s,b)=>s+b.ymax,0)/topBoxes.length
} : { xmin: 360, ymin: 13, xmax: 456, ymax: 94 };

let faceX = ((bestBox.xmin + bestBox.xmax) / 2) * scale;
let faceY = ((bestBox.ymin + bestBox.ymax) / 2) * scale;
let faceW = (bestBox.xmax - bestBox.xmin) * scale;

// Tighter crop: 2.8x face width (was 3.5) = more zoomed in
let cropW = faceW * 2.8;
if (cropW < 260) cropW = 260;
if (cropW > 680) cropW = 680;
let cropH = cropW * (9/16);

// FIX: push crop UP so the face isn't cut at the top.
// faceY/2.0 = face center at 50% from top (was 40%). Ensures head is fully visible.
let startX = faceX - (cropW / 2);
let startY = faceY - (cropH / 2.0);

// Also shift down by 30px to show chin + a bit of shoulder
startY = startY + 30;

if (startX < 0) startX = 0;
if (startY < 0) startY = 0;
if (startX + cropW > videoRealW) startX = videoRealW - cropW;
if (startY + cropH > videoRealH) startY = videoRealH - cropH;

return [{ json: { cam_x: Math.floor(startX), cam_y: Math.floor(startY), cam_w: Math.floor(cropW), cam_h: Math.floor(cropH), ai_found: topBoxes.length > 0 } }];

const clipData = $input.first().json;
const viral = clipData.viral_structure;
if (!viral || Object.keys(viral).length === 0) return [{ json: { error: "No viral structure", clip_title: clipData.title } }];

const whisperData = $('3. Groq Whisper').first().json;
const whisperWords = whisperData.words || (whisperData.x_groq && whisperData.x_groq.words) || [];

function findTimeForText(targetText) {
    if (!targetText || typeof targetText !== 'string') return null;
    const tWords = targetText.toLowerCase().replace(/[^a-z0-9\s]/g,'').split(/\s+/).filter(w=>w);
    if (tWords.length === 0) return null;
    let bestStart=-1,bestEnd=-1,maxMatch=0;
    for (let i=0;i<whisperWords.length;i++) {
        let matchCount=0,tIdx=0,endIdx=i;
        for (let wIdx=i;wIdx<Math.min(whisperWords.length,i+tWords.length*2.5);wIdx++) {
            if (tIdx>=tWords.length) break;
            const wWord=(whisperWords[wIdx].word||"").toLowerCase().replace(/[^a-z0-9]/g,'');
            if (!wWord) continue;
            if (wWord===tWords[tIdx]){matchCount++;tIdx++;endIdx=wIdx;}
            else if (tIdx+1<tWords.length&&wWord===tWords[tIdx+1]){matchCount++;tIdx+=2;endIdx=wIdx;}
            else if (tIdx+2<tWords.length&&wWord===tWords[tIdx+2]){matchCount++;tIdx+=3;endIdx=wIdx;}
        }
        if (matchCount>maxMatch&&(matchCount/tWords.length)>0.40){
            maxMatch=matchCount;bestStart=i;bestEnd=endIdx;
            if (matchCount===tWords.length) break;
        }
    }
    if (bestStart!==-1) return {start:whisperWords[bestStart].start,end:whisperWords[bestEnd].end};
    return null;
}

const BUFFER=0.4;
let rawSegs=[];
for (const [key,value] of Object.entries(viral)) {
    const texts=Array.isArray(value)?value:[value];
    for (const text of texts) {
        if (typeof text!=='string') continue;
        const t=findTimeForText(text);
        if (t) rawSegs.push({name:key,start:Math.max(0,t.start-BUFFER),end:t.end+BUFFER});
    }
}
if (rawSegs.length===0) rawSegs.push({name:'fallback',start:0,end:45});

// Sort and merge overlapping/adjacent segments
rawSegs.sort((a,b)=>a.start-b.start);
const MERGE_GAP=1.5;
const merged=[];
for (const seg of rawSegs) {
    const last=merged[merged.length-1];
    if (!last||seg.start>last.end+MERGE_GAP) merged.push({...seg});
    else { last.end=Math.max(last.end,seg.end); last.name+='+'+seg.name; }
}

// Silence cutting: cut gaps >1.8s unless shock word precedes them
const SILENCE_CUT=1.8,MIN_SUB=1.2;
const SHOCK=new Set(['wait','no','oh','bro','what','dude','wow','yo','omg','nah','stop']);
const finalSegs=[];
for (const seg of merged) {
    const segWords=whisperWords.filter(w=>w.start>=seg.start-0.1&&w.end<=seg.end+0.1);
    if (segWords.length<2){finalSegs.push(seg);continue;}
    let subStart=seg.start;
    for (let i=0;i<segWords.length-1;i++) {
        const gap=segWords[i+1].start-segWords[i].end;
        if (gap>SILENCE_CUT){
            const wb=(segWords[i].word||'').toLowerCase().replace(/[^a-z]/g,'');
            if (!SHOCK.has(wb)){
                const subEnd=segWords[i].end+0.15;
                if (subEnd-subStart>=MIN_SUB) finalSegs.push({...seg,start:subStart,end:subEnd});
                subStart=segWords[i+1].start-0.15;
            }
        }
    }
    if (seg.end-subStart>=MIN_SUB) finalSegs.push({...seg,start:subStart,end:seg.end});
}

// ── DURATION ENFORCEMENT: target 40-55 seconds ──────────────────────────────
const TARGET_MIN=40, TARGET_MAX=55;
const totalDur=finalSegs.reduce((sum,s)=>sum+(s.end-s.start),0);

if (totalDur<TARGET_MIN && finalSegs.length>0) {
    // Expand each segment proportionally to reach 40s minimum
    const deficit=TARGET_MIN-totalDur;
    const expandPerSeg=deficit/finalSegs.length;
    finalSegs.forEach(s=>{
        s.start=Math.max(0,s.start-expandPerSeg*0.3);
        s.end=s.end+expandPerSeg*0.7;
    });
}
if (totalDur>TARGET_MAX && finalSegs.length>1) {
    // Trim from the last segment to stay under 55s
    const excess=totalDur-TARGET_MAX;
    finalSegs[finalSegs.length-1].end=Math.max(
        finalSegs[finalSegs.length-1].start+5,
        finalSegs[finalSegs.length-1].end-excess
    );
}

return finalSegs.map((seg,i)=>({ json:{
    segment_name:seg.name, segment_order:i+1,
    start:seg.start, end:seg.end, duration:seg.end-seg.start,
    clip_title:clipData.title, theme:clipData.theme||"None",
    structure_type:clipData.structure_type||"Standard"
}}));

const all = $input.all().map(item => item.json).sort((a, b) => a.segment_order - b.segment_order);
const clipTitle = all[0].clip_title;
const streamFile = $('Edit Fields').first().json.stream_file;

// Drop segments shorter than 0.5s — ffmpeg chokes on near-zero durations
const segments = all.filter(s => (s.end - s.start) >= 0.5);
if (segments.length === 0) {
    // Emergency fallback: just take first 40 seconds
    segments.push({ ...all[0], start: 0, end: 40 });
}

let filterComplex = "";
let concatInputs = "";
segments.forEach((seg, i) => {
    filterComplex += `[0:v]trim=start=${seg.start}:end=${seg.end},setpts=PTS-STARTPTS[v${i}];`;
    filterComplex += `[0:a]atrim=start=${seg.start}:end=${seg.end},asetpts=PTS-STARTPTS[a${i}];`;
    concatInputs += `[v${i}][a${i}]`;
});
filterComplex += `${concatInputs}concat=n=${segments.length}:v=1:a=1[v_out][a_out]`;

// +faststart: writes moov atom at the START of the file = always readable
const ffmpegCmd = `ffmpeg -loglevel error -y -i "/files/inputs/${streamFile}" -filter_complex "${filterComplex}" -map "[v_out]" -map "[a_out]" -c:v libx264 -preset ultrafast -crf 23 -c:a aac -movflags +faststart "/files/temp/concatenated_clip.mp4"`;
return [{ json: { command: ffmpegCmd, output_file: "/files/temp/concatenated_clip.mp4", clip_title: clipTitle } }];

const FONT_SIZE = 55;
const HIGHLIGHT_COLOR = "&H00FFFF&";
const MAIN_COLOR = "&HFFFFFF&";
function getSubtitleY(time) { return 485; }
function formatTimeASS(seconds) { const d = new Date(0); d.setMilliseconds(seconds * 1000); return d.getUTCHours() + ":" + d.getUTCMinutes().toString().padStart(2,'0') + ":" + d.getUTCSeconds().toString().padStart(2,'0') + "." + Math.floor(d.getUTCMilliseconds()/10).toString().padStart(2,'0'); }

const subInput = $('7d. Get Subtitles (SRT)').first().json;
let wordData = subInput.words || (subInput.x_groq && subInput.x_groq.words) || [];

const camConfig = $('Parse Cam Config').first().json;
const camW = camConfig.cam_w, camH = camConfig.cam_h, camX = camConfig.cam_x, camY = camConfig.cam_y;

const realFiles = ($('Get Meme List').first().json.stdout || "").split('\n').filter(f => f.length > 3);
function getBestMatch(aiFile) { if (!aiFile) return null; const clean = String(aiFile).toLowerCase(); if (realFiles.includes(aiFile)) return aiFile; return realFiles.find(f => f.toLowerCase().includes(clean.replace('.mp3',''))) || null; }

let rawCaption = "WAIT FOR IT", screams = [], memes = [];
try {
  let raw = $('Context Merge Agent').first().json.output || '{}'; raw = raw.replace(/\`\`\`json/g, '').replace(/\`\`\`/g, '').trim(); const parsed = JSON.parse(raw);
  if (parsed.viral_caption) rawCaption = parsed.viral_caption;
  if (parsed.screams) screams = parsed.screams;
  if (parsed.screams_or_full_cam) screams = screams.concat(parsed.screams_or_full_cam);
  if (parsed.memes) memes = parsed.memes;
} catch(e) {}

let audioInputs = [], audioFilters = "", activeMemes = 0;

if (memes && memes.length > 0) {
  memes.forEach(m => {
    if (activeMemes >= 10 || !m.file) return;
    const realFile = getBestMatch(m.file);
    if (realFile) {
      const time = parseFloat(m.timestamp);
      if (!isNaN(time)) {
         const delay = Math.floor(time * 1000);
         audioInputs.push(`-i "/files/memes/${realFile}"`);
         const memeVol = (typeof m.volume === 'number' ? m.volume : 0.35);
         audioFilters += `[${activeMemes+1}:a]volume=${memeVol},adelay=${delay}|${delay}[meme${activeMemes+1}];`;
         activeMemes++;
      }
    }
  });
}

let audioMixFilter = "";
if (activeMemes > 0) {
  let mixInputs = "[0:a]";
  for (let k = 1; k <= activeMemes; k++) mixInputs += `[meme${k}]`;
  audioMixFilter = audioFilters + mixInputs + `amix=inputs=${activeMemes + 1}:duration=first[a_out]`;
}

let zoomEnable = screams.length > 0 ? screams.map(s => `between(t,${s.start || 0},${s.end || 0})`).join("+") : "between(t,0,0)";

let assContent = `[Script Info]\nScriptType: v4.00+\nPlayResX: 720\nPlayResY: 1280\n[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\nStyle: ViralSubs,Lilita One,${FONT_SIZE},${MAIN_COLOR},&H000000FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,3,2,5,10,10,10,1\nStyle: ViralCaption,Lilita One,65,&H00FFFF&,&H000000FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,4,2,8,40,40,30,1\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n`;

if (wordData.length > 0) {
  let i = 0;
  while (i < wordData.length) {
    let chunk = [wordData[i]], charCount = String(wordData[i].word||"").length, lookAhead = 1;
    while (i + lookAhead < wordData.length) {
      let nWord = wordData[i + lookAhead];
      if (nWord.start - wordData[i+lookAhead-1].end > 0.5) break;
      if (charCount + String(nWord.word||"").length < 14) { chunk.push(nWord); charCount += String(nWord.word||"").length; lookAhead++; } else break;
    }

    let cStart = chunk[0].start, cEnd = chunk[chunk.length-1].end; // REMOVED +0.2 overlapping padding!
    for (let j = 0; j < chunk.length; j++) {
      let wStart = Math.max(cStart, chunk[j].start);
      let wEnd = j < chunk.length-1 ? chunk[j+1].start : cEnd; // ENDs exactly when next word STARTS

      const lText = chunk.map((w, idx) => idx === j ? `{\\c${HIGHLIGHT_COLOR}\\t(0,50,\\fscx115\\fscy115)\\t(50,150,\\fscx100\\fscy100)}${String(w.word||"").trim().toUpperCase()}{\\c${MAIN_COLOR}}` : String(w.word||"").trim().toUpperCase()).join(" ");
      assContent += `Dialogue: 1,${formatTimeASS(wStart)},${formatTimeASS(wEnd)},ViralSubs,,0,0,0,,{\\pos(360,${getSubtitleY(wStart)})}${lText}\n`;
    }
    i += chunk.length;
  }
}
assContent += `Dialogue: 2,0:00:00.00,0:00:05.50,ViralCaption,,0,0,0,,{\\an8\\fad(0,300)\\t(0,100,\\fscx120\\fscy120)\\t(100,300,\\fscx100\\fscy100)}${rawCaption.replace(/'/g,'').toUpperCase()}\n`;

const bgPart = "[0:v]split=3[v_bg][v_game][v_cam];[v_bg]scale=720:1280:force_original_aspect_ratio=increase,crop=720:1280,boxblur=20:5[bg]";
const gamePart = "[v_game]crop=trunc(ih*0.88/2)*2:trunc(ih*0.88/2)*2:(iw-ow)/2:0,scale=720:720,drawbox=x=0:y=0:w=720:h=720:color=white:t=6[game_bordered]"; 
const camPart = "[v_cam]crop=" + camW + ":" + camH + ":" + camX + ":" + camY + ",split=2[cam_small][cam_full];[cam_small]scale=720:400,drawbox=x=0:y=0:w=720:h=ih:color=white:t=6[cam_bordered];[cam_full]scale=-1:1280,crop=720:1280:exact=1[cam_zoom]";
const overlayPart = "[bg][cam_bordered]overlay=0:0[bg2];[bg2][game_bordered]overlay=0:H-h[base];[base][cam_zoom]overlay=0:0:enable='" + zoomEnable + "'[outv];[outv]ass=/files/temp/subs.ass:fontsdir=/files/inputs[v]";

let filter = bgPart + ";" + gamePart + ";" + camPart + ";" + overlayPart;
const title = $('Loop Clips').first().json.title || "output_clip";
let outputFile = "/files/outputs/" + title + ".mp4";

let cmd = activeMemes > 0 
  ? `ffmpeg -loglevel error -y -i "/files/temp/concatenated_clip.mp4" ${audioInputs.join(" ")} -filter_complex "${filter};${audioMixFilter}" -map "[v]" -map "[a_out]" -c:v libx264 -preset fast -crf 23 -c:a aac "${outputFile}"`
  : `ffmpeg -loglevel error -y -i "/files/temp/concatenated_clip.mp4" -filter_complex "${filter}" -map "[v]" -map 0:a -c:v libx264 -preset fast -crf 23 -c:a aac "${outputFile}"`;

return [{json: {command: cmd}, binary: {data: {data: Buffer.from(assContent).toString('base64'), mimeType: 'text/plain', fileName: 'subs.ass'}}}];

