let whisperData = null;

try {
  const items = $input.all();
  if (items && items[0] && items[0].json && items[0].json.text) {
    whisperData = items[0].json;
  }
} catch(e) {}

if (!whisperData) {
  try {
    const w = $('3. Groq Whisper').first().json;
    if (w && w.text && w.text.length > 10) whisperData = w;
  } catch(e) {}
}
if (!whisperData) {
  try {
    const w2 = $('3. Groq Whisper Fallback').first().json;
    if (w2 && w2.text && w2.text.length > 10) whisperData = w2;
  } catch(e) {}
}

if (!whisperData || !whisperData.text) {
    throw new Error('CRITICAL ERROR: Transcript text is missing. Run Whisper node first.');
}

const rawText = whisperData.text;
const durationMinutes = (whisperData.duration || 1800) / 60;

// Break into sentences and add Line Numbers
const sentences = rawText.match(/[^.!?]+[.!?]+/g) || [rawText];
const numberedLines = sentences.map((s, i) => '[L' + (i+1) + '] ' + s.trim());

// Calculate chunks — cap at 4 to limit parallel Groq calls
let numChunks = Math.max(1, Math.round(durationMinutes / 7.5));
numChunks = Math.min(numChunks, 4);

const linesPerChunk = Math.ceil(numberedLines.length / numChunks);
const overlap = 20; 

// TOKEN BUDGET: llama-3.3-70b-versatile = 12,000 TPM limit
const MAX_CHUNK_CHARS = 10000;

const results = [];
for (let i = 0; i < numChunks; i++) {
  const start = Math.max(0, i * linesPerChunk - overlap);
  const end = Math.min(numberedLines.length, (i + 1) * linesPerChunk + overlap);

  // Build chunk text and HARD-CAP at 10,000 chars
  let chunkText = numberedLines.slice(start, end).join('\n');
  if (chunkText.length > MAX_CHUNK_CHARS) {
    // Trim from the end — keep the start (line numbers stay sequential)
    chunkText = chunkText.substring(0, MAX_CHUNK_CHARS) + '\n[... chunk trimmed to fit token limit ...]';
  }

  const prompt = 
    'SYSTEM: You are a viral gaming content scout. Read the numbered transcript chunk and extract the absolute best, most explosive moments.\n\n' +
    'SCAN FOR:\n' +
    '- [BET]: Dare/challenge (e.g., "if you get X I will...").\n' +
    '- [DROP]: Rare item actually dropping + chaos/screaming.\n' +
    '- [ROAST]: Brutal insult.\n' +
    '- [CHAOS]: Overlapping panic/screaming.\n\n' +
    'OUTPUT RULES (CRITICAL):\n' +
    '1. Select 1 to 3 viral moments from this chunk. If the chunk is boring (just normal gameplay/farming), you may output 0.\n' +
    '2. For EACH moment, you MUST extract a MASSIVE, continuous block of AT LEAST 25 to 35 lines.\n' +
    '3. You must include the full context setup (approx 15 lines BEFORE the climax) and the full reaction (approx 15 lines AFTER the climax).\n' +
    '4. DO NOT summarize or paraphrase. Copy the exact lines with their [Lx] timestamps.\n' +
    '5. Format each moment clearly with a header (e.g., "=== MOMENT 1: [DROP] ===").\n\n' +
    '--- CHUNK ' + (i+1) + '/' + numChunks + ' ---\n' +
    chunkText;

  results.push({ json: { prompt, chunk_index: i+1 } });
}

return results;

const items = $input.all();
let allSnippets = "";

// Gather all the plain text snippets from the Scout pass
items.forEach((item, index) => {
  allSnippets += `\n\n=== SCOUTED MOMENTS CHUNK ${index + 1} ===\n`;
  allSnippets += item.json.text || item.json.output || "";
});

// TOKEN SHIELD: Prevent Groq 413 "Request too large" error.
// Groq limit is 12,000 tokens. 1 token ≈ 4 characters.
// Max safe prompt size is ~38,000 chars. We cap snippets at 28,000 to leave room for the system prompt and output.
if (allSnippets.length > 28000) {
    allSnippets = allSnippets.substring(0, 28000) + "\n\n[... REMAINING SNIPPETS TRUNCATED TO PREVENT GROQ CRASH ...]";
}

// Pull the Global Summary for title context
let streamContext = "";
try {
  const summaryRaw = $('1. Global Summary AI').first().json.output || $('1. Global Summary Fallback').first().json.output || "{}";
  const summary = JSON.parse(summaryRaw.replace(/```json/gi,'').replace(/```/g,'').trim());
  streamContext = [
    summary.game ? "GAME: " + summary.game : "",
    summary.global_summary ? "STREAM SUMMARY: " + summary.global_summary : "",
    summary.vibe ? "VIBE: " + summary.vibe : "",
    (summary.key_themes && summary.key_themes.length) ? "KEY THEMES: " + summary.key_themes.join(", ") : ""
  ].filter(Boolean).join("\n");
} catch(e) {}

// DYNAMIC LIMIT: Allow the AI to output fewer clips if the quality is low.
const maxClips = 3; 

// Updated schema including the mandatory Chain of Thought and adversarial hook critique
const jsonSchema = '{"clips":[{"clip_number":1,"estimated_vod_segment":"X-Y minutes","compliance_check":{"did_event_actually_happen":"Explain briefly why this is a real drop and not an anti-climax like \\"I didn\'t get it\\".","hook_critique":"Argue why a viewer would swipe away from this hook in the first 2 seconds. Be a harsh critic. If it is just a generic reaction, REPLACE IT.","is_title_a_teaser":"Explain why your title teases the outcome without spoiling the exact item name."},"title":"YOUR AI-GENERATED TITLE HERE","theme":"Core viral theme","structure_type":"Structure Name","viral_structure":{"Hook":"VERBATIM line — mid-action, never a generic reaction word.","Build_up":["VERBATIM line","VERBATIM line","VERBATIM line"],"Payoff":"VERBATIM line — names specific item/number.","Outro":"VERBATIM line"}}]}';

const prompt = 
  'SYSTEM: You are an expert YouTube Shorts director. You have been given a highly concentrated list of the most explosive moments from a gaming stream.\n\n' +

  (streamContext ? '=== STREAM CONTEXT (use this to write great titles) ===\n' + streamContext + '\n\n' : '') +

  '=== STEP 1: REVIEW AND SELECT (CRITICAL RULE) ===\n' +
  'You MUST read every single snippet provided.\n' +
  'Mentally score each moment based on chaos and having a definitive PAYOFF.\n' +
  'CRITICAL BAN: You MUST absolutely reject any moment that ends in an anti-climax. If the streamer says "I did not get it", "Imagine if...", or "I wish", throw the moment away. ONLY select moments where the rare drop/event ACTUALLY HAPPENS on screen.\n' +
  'Select ONLY the absolute best, highest-scoring moments. Quality over quantity.\n\n' +

  '=== STEP 2: BUILD CLIPS ===\n' +
  'For your selected moments, build a 40-55s clip using this structure:\n\n' +
  '[HOOK] A verbatim line starting IN THE MIDDLE of the action.\n' +
  '- CRITICAL BAN: The Hook CANNOT be the exact same line as the Payoff.\n' +
  '- CRITICAL BAN: If the quote is just "No way", "Oh my god", "Wait", or "What" without naming a specific item/number, REJECT IT and pick a different line.\n' +
  '[BUILD_UP] Exactly 3 verbatim lines building energy leading to the payoff.\n' +
  '[PAYOFF] The climax verbatim quote.\n' +
  '- MUST PASS: It MUST name the specific item/player/number. It MUST be the moment the item is actually obtained.\n' +
  '[OUTRO] A verbatim line directly reacting to the Payoff.\n\n' +

  '=== STEP 3: WRITE THE TITLE ===\n' +
  'Write a YouTube Shorts title that makes people STOP SCROLLING.\n' +
  '- TEASE the payoff — do NOT state it. The viewer must NEED to watch to find out.\n' +
  '- BAD: "Sammy Spawns Fat Sammy?!" (Tells them what happens)\n' +
  '- GOOD: "Sammy Actually Spawned THIS On Stream 😱" (Forces them to watch)\n' +
  '- Max 60 chars.\n' +
  '- Use tension words: "Actually", "Just", "On Stream", "For Real".\n' +
  '- BANNED: "Moment", "He Gets", "He Pulls", "Drops", "Insane".\n\n' +

  '=== STEP 4: CHAIN OF THOUGHT VALIDATION ===\n' +
  'To ensure you followed the rules, you MUST output a "compliance_check" JSON object for EVERY clip before you output the "viral_structure". You must prove the event actually happened, critique your own hook, and ensure the title is a teaser.\n\n' +

  '=== OUTPUT RULES ===\n' +
  'Raw valid JSON only. No markdown. No explanation.\n' +
  'You may output anywhere from 1 to ' + maxClips + ' clips.\n' +
  'CRITICAL: If the transcript only contains 1 genuinely explosive, rule-passing moment, output an array containing ONLY 1 CLIP. Do not lower your standards just to output more clips. Quality is the ONLY thing that matters.\n' +
  'Return a JSON object with a "clips" array matching this schema exactly:\n' +
  jsonSchema + '\n\n' +
  '--- SCOUTED SNIPPETS ---\n' +
  allSnippets;

return [{ json: { prompt, maxClips } }];

const items = $input.all();
let allClips = [];

let streamerName = "Streamer";
try {
  streamerName = $('Config').item.json.streamer_name || "Streamer";
} catch(e) {}

for (const item of items) {
  let content = item.json.output || item.json.text || '{}';

  // 1. Clean markdown formatting
  content = content.replace(/\`\`\`json/gi, '').replace(/\`\`\`/g, '').trim();

  // 2. Auto-Fix common AI JSON typos
  content = content.replace(/\}\}\},\{/g, '}},{'); // Fixes the exact extra bracket error you just got
  content = content.replace(/\}\}\]\}/g, '}}]}');
  content = content.replace(/\]\]/g, ']'); 
  content = content.replace(/\}\,\]/g, '}]'); 

  try { 
    // 3. Try parsing the repaired JSON
    const aiData = JSON.parse(content); 
    if (aiData.clips && Array.isArray(aiData.clips)) {
      allClips = allClips.concat(aiData.clips);
    }
    continue; 
  } catch (e) {
    // 4. BULLETPROOF FALLBACK: If JSON is STILL broken, forcefully extract using Regex
    const clipBlocks = content.split(/"clip_number"\s*:/i);

    if (clipBlocks.length > 1) {
        for (let i = 1; i < clipBlocks.length; i++) {
            const block = clipBlocks[i];

            const titleMatch = block.match(/"title"\s*:\s*"([^"]+)"/i);
            const hookMatch = block.match(/"Hook"\s*:\s*"([^"]+)"/i);
            const payoffMatch = block.match(/"Payoff"\s*:\s*"([^"]+)"/i);
            const outroMatch = block.match(/"Outro"\s*:\s*"([^"]+)"/i);

            if (hookMatch && payoffMatch) {
                allClips.push({
                    title: titleMatch ? titleMatch[1] : `Recovered_Clip_${i}`,
                    viral_structure: {
                        Hook: hookMatch[1],
                        Build_up: ["(Recovered Build-up)", "(Recovered Build-up)", "(Recovered Build-up)"],
                        Payoff: payoffMatch[1],
                        Outro: outroMatch ? outroMatch[1] : "(Recovered Outro)"
                    }
                });
            }
        }
    }
  }
}

// 5. If everything completely fails, use the backup
if (allClips.length === 0) {
    return [{ json: { viral_structure: { Hook: "Error", Payoff: "Failed to parse AI output" }, title: streamerName + "_Backup_Clip", virality_score: 0, structure_type: "Standard" } }];
}

// 6. Format the final output cleanly for your next nodes
return allClips.map((clip, index) => {
    return { json: {
        viral_structure: clip.viral_structure,
        title: clip.title || `${streamerName}_Clip_${index + 1}_${Math.floor(Math.random() * 9999)}`,
        virality_score: clip.virality_score || 0,
        theme: clip.theme || "Gaming",
        structure_type: clip.structure_type || "Standard",
        estimated_segment: clip.estimated_vod_segment || "Unknown"
    }};
});
